NOW = datetime(2030, 1, 7, 8, 0)  # A Monday.
TODAY = NOW.date()


class TrackerTestCase(unittest.TestCase):
    def setUp(self):
        self.tracker = MediTrack()
        self.pro = self.tracker.add_professional("Dr Ada Obi", "Cardiology").id
        self.pro2 = self.tracker.add_professional("Dr Sam Roy", "Dermatology").id
        self.client = self.tracker.add_client("Ann Lee", "1990-05-01", "+44 7700 900123").id
        self.client2 = self.tracker.add_client("Ben Cole", "1985-02-14", "01782 733000").id

    def book(self, start, duration=30, pro=None, client=None):
        return self.tracker.book_appointment(
            pro or self.pro, client or self.client, start, duration, "Check-up", now=NOW
        )


class PeopleTests(TrackerTestCase):
    def test_ids_are_sequential_and_lookup_ignores_case(self):
        self.assertEqual(self.pro, "PRO-0001")
        self.assertEqual(self.pro2, "PRO-0002")
        self.assertEqual(self.tracker.get_client("cli-0001").name, "Ann Lee")

    def test_blank_name_rejected(self):
        with self.assertRaises(ValidationError):
            self.tracker.add_professional("   ", "Cardiology")

    def test_name_length_boundary(self):
        self.tracker.add_professional("x" * 100, "Cardiology")
        with self.assertRaises(ValidationError):
            self.tracker.add_professional("x" * 101, "Cardiology")

    def test_rejected_people_use_no_id(self):
        with self.assertRaises(ValidationError):
            self.tracker.add_professional("", "Cardiology")
        self.assertEqual(self.tracker.add_professional("A", "B").id, "PRO-0003")
        with self.assertRaises(ValidationError):
            self.tracker.add_client("A", "2000-01-01", "bad")
        self.assertEqual(self.tracker.add_client("A", "2000-01-01", "01782 733000").id, "CLI-0003")

    def test_birth_date_boundary(self):
        self.tracker.add_client("Born Today", TODAY, "01782 733000", today=TODAY)
        with self.assertRaises(ValidationError):
            self.tracker.add_client("Born Later", "2030-01-08", "01782 733000", today=TODAY)

    def test_impossible_date_rejected(self):
        with self.assertRaises(ValidationError):
            self.tracker.add_client("Bad Date", "2001-02-30", "01782 733000")

    def test_bad_phone_rejected(self):
        for phone in ("", "abc123", "12345"):
            with self.subTest(phone=phone), self.assertRaises(ValidationError):
                self.tracker.add_client("Bad Phone", "2000-01-01", phone)

    def test_search_matches_name_phone_and_id(self):
        self.assertEqual([c.id for c in self.tracker.search_clients("ann")], [self.client])
        self.assertEqual([c.id for c in self.tracker.search_clients("733000")], [self.client2])
        self.assertEqual([c.id for c in self.tracker.search_clients("CLI-0002")], [self.client2])
        self.assertEqual(self.tracker.search_clients("nobody"), [])
        self.assertEqual(len(self.tracker.search_clients()), 2)


class BookingTests(TrackerTestCase):
    def test_book_and_list_in_time_order(self):
        later = self.book("2030-01-08 11:00")
        earlier = self.book("2030-01-08 09:00")
        ids = [a.id for a in self.tracker.list_appointments()]
        self.assertEqual(ids, [earlier.id, later.id])

    def test_adjacent_appointments_are_allowed(self):
        self.book("2030-01-08 09:00", 30)
        self.book("2030-01-08 09:30", 30)
        self.book("2030-01-08 08:30", 30)
        self.assertEqual(len(self.tracker.list_appointments()), 3)

    def test_overlap_for_professional_rejected(self):
        self.book("2030-01-08 09:00", 30)
        for start in ("2030-01-08 08:45", "2030-01-08 09:00", "2030-01-08 09:29"):
            with self.subTest(start=start), self.assertRaises(ConflictError):
                self.book(start, 30, client=self.client2)

    def test_overlap_for_client_rejected(self):
        self.book("2030-01-08 09:00", 30)
        with self.assertRaises(ConflictError):
            self.book("2030-01-08 09:15", 30, pro=self.pro2)

    def test_new_appointment_enclosing_existing_rejected(self):
        self.book("2030-01-08 09:30", 15)
        with self.assertRaises(ConflictError):
            self.book("2030-01-08 09:00", 120, client=self.client2)

    def test_different_people_may_share_a_time(self):
        self.book("2030-01-08 09:00")
        self.book("2030-01-08 09:00", pro=self.pro2, client=self.client2)
        self.assertEqual(len(self.tracker.list_appointments()), 2)

    def test_start_boundary(self):
        self.book(NOW)
        with self.assertRaises(ValidationError):
            self.book("2030-01-07 07:59", client=self.client2, pro=self.pro2)

    def test_duration_boundaries(self):
        self.book("2030-01-08 09:00", 5)
        self.book("2030-01-09 09:00", 480)
        for duration in (4, 481, "ten", ""):
            with self.subTest(duration=duration), self.assertRaises(ValidationError):
                self.book("2030-01-10 09:00", duration)

    def test_unknown_people_rejected(self):
        with self.assertRaises(NotFoundError):
            self.book("2030-01-08 09:00", pro="PRO-9999")
        with self.assertRaises(NotFoundError):
            self.book("2030-01-08 09:00", client="CLI-9999")

    def test_failed_booking_uses_no_id(self):
        self.book("2030-01-08 09:00")
        with self.assertRaises(ConflictError):
            self.book("2030-01-08 09:00")
        self.assertEqual(self.book("2030-01-08 10:00").id, "APT-0002")


class AppointmentChangeTests(TrackerTestCase):
    def test_reschedule_can_overlap_its_own_old_time(self):
        appointment = self.book("2030-01-08 09:00", 30)
        self.tracker.reschedule_appointment(appointment.id, "2030-01-08 09:15", now=NOW)
        self.assertEqual(appointment.start, datetime(2030, 1, 8, 9, 15))
        self.book("2030-01-08 09:00", 15)

    def test_failed_reschedule_changes_nothing(self):
        first = self.book("2030-01-08 09:00", 30)
        self.book("2030-01-08 10:00", 30)
        with self.assertRaises(ConflictError):
            self.tracker.reschedule_appointment(first.id, "2030-01-08 10:15", now=NOW)
        self.assertEqual(first.start, datetime(2030, 1, 8, 9, 0))
        with self.assertRaises(ConflictError):
            self.book("2030-01-08 09:00", 30)

    def test_cancel_frees_the_time(self):
        appointment = self.book("2030-01-08 09:00")
        self.tracker.cancel_appointment(appointment.id)
        self.assertEqual(appointment.status, CANCELLED)
        self.book("2030-01-08 09:00")

    def test_complete_only_after_start(self):
        appointment = self.book("2030-01-08 09:00")
        with self.assertRaises(ConflictError):
            self.tracker.complete_appointment(appointment.id, now=NOW)
        self.tracker.complete_appointment(appointment.id, now=datetime(2030, 1, 8, 9, 0))
        self.assertEqual(appointment.status, COMPLETED)

    def test_finished_appointment_cannot_change(self):
        appointment = self.book("2030-01-08 09:00")
        self.tracker.cancel_appointment(appointment.id)
        with self.assertRaises(ConflictError):
            self.tracker.cancel_appointment(appointment.id)
        with self.assertRaises(ConflictError):
            self.tracker.reschedule_appointment(appointment.id, "2030-01-09 09:00", now=NOW)

    def test_filters_combine(self):
        first = self.book("2030-01-08 09:00")
        second = self.book("2030-01-09 09:00", pro=self.pro2)
        self.tracker.cancel_appointment(second.id)
        self.assertEqual(self.tracker.list_appointments(professional_id=self.pro), [first])
        self.assertEqual(self.tracker.list_appointments(on_date="2030-01-09"), [second])
        self.assertEqual(self.tracker.list_appointments(status=CANCELLED), [second])
        self.assertEqual(
            self.tracker.list_appointments(professional_id=self.pro, status=CANCELLED), []
        )
        with self.assertRaises(ValidationError):
            self.tracker.list_appointments(status="unknown")


class FreeSlotTests(TrackerTestCase):
    def slot(self, duration=30, after=None, now=NOW):
        return self.tracker.find_next_free_slot(self.pro, self.client, duration, after, now=now)

    def test_empty_schedule_starts_at_opening_time(self):
        self.assertEqual(self.slot(), datetime(2030, 1, 7, 9, 0))

    def test_rounds_up_to_slot_boundary(self):
        self.assertEqual(self.slot(after="2030-01-07 10:07"), datetime(2030, 1, 7, 10, 15))
        self.assertEqual(self.slot(after="2030-01-07 10:15"), datetime(2030, 1, 7, 10, 15))

    def test_skips_a_run_of_appointments(self):
        self.book("2030-01-07 09:00", 30)
        self.book("2030-01-07 09:30", 40)
        self.assertEqual(self.slot(), datetime(2030, 1, 7, 10, 15))

    def test_considers_the_clients_schedule_too(self):
        self.book("2030-01-07 09:00", 60, pro=self.pro2)
        self.assertEqual(self.slot(), datetime(2030, 1, 7, 10, 0))

    def test_gap_too_short_is_skipped(self):
        self.book("2030-01-07 09:30", 30)
        self.assertEqual(self.slot(60), datetime(2030, 1, 7, 10, 0))

    def test_slot_may_end_exactly_at_closing(self):
        self.assertEqual(self.slot(30, "2030-01-07 16:30"), datetime(2030, 1, 7, 16, 30))

    def test_late_slot_moves_to_next_day(self):
        self.assertEqual(self.slot(30, "2030-01-07 16:45"), datetime(2030, 1, 8, 9, 0))

    def test_friday_evening_moves_to_monday(self):
        self.assertEqual(self.slot(30, "2030-01-11 16:45"), datetime(2030, 1, 14, 9, 0))

    def test_saturday_moves_to_monday(self):
        self.assertEqual(self.slot(30, "2030-01-12 11:00"), datetime(2030, 1, 14, 9, 0))

    def test_search_never_starts_in_the_past(self):
        self.assertEqual(self.slot(after="2020-01-01 09:00"), datetime(2030, 1, 7, 9, 0))

    def test_duration_longer_than_workday_rejected(self):
        self.assertEqual(self.slot(480), datetime(2030, 1, 7, 9, 0))
        with self.assertRaises(ValidationError):
            self.tracker.find_next_free_slot(self.pro, self.client, 480 + 1, now=NOW)

    def test_returned_slot_can_be_booked(self):
        self.book("2030-01-07 09:00", 30)
        self.book(self.slot(), 30)


class PrescriptionTests(TrackerTestCase):
    def issue(self, medication="Amoxicillin", start="2030-01-07", days=7, times=3):
        return self.tracker.issue_prescription(
            self.client, self.pro, medication, "500 mg", times, start, days
        )

    def test_end_date_and_total_doses(self):
        prescription = self.issue()
        self.assertEqual(prescription.end_date, date(2030, 1, 13))
        self.assertEqual(prescription.total_doses, 21)

    def test_active_period_boundaries(self):
        prescription = self.issue()
        self.assertFalse(prescription.is_active(date(2030, 1, 6)))
        self.assertTrue(prescription.is_active(date(2030, 1, 7)))
        self.assertTrue(prescription.is_active(date(2030, 1, 13)))
        self.assertFalse(prescription.is_active(date(2030, 1, 14)))

    def test_number_limits(self):
        self.issue("A", times=1, days=1)
        self.issue("B", times=12, days=365)
        for times, days in ((0, 7), (13, 7), (3, 0), (3, 366), ("x", 7)):
            with self.subTest(times=times, days=days), self.assertRaises(ValidationError):
                self.issue("C", times=times, days=days)

    def test_overlapping_course_of_same_medication_rejected(self):
        self.issue("Amoxicillin")
        with self.assertRaises(ConflictError):
            self.issue(" amoxicillin ", start="2030-01-13")

    def test_next_day_course_allowed(self):
        self.issue("Amoxicillin")
        self.issue("Amoxicillin", start="2030-01-14")

    def test_other_client_and_medication_allowed(self):
        self.issue("Amoxicillin")
        self.issue("Ibuprofen")
        self.tracker.issue_prescription(
            self.client2, self.pro, "Amoxicillin", "500 mg", 3, "2030-01-07", 7
        )

    def test_stop_takes_effect_on_stop_date(self):
        prescription = self.issue()
        self.tracker.stop_prescription(prescription.id, "2030-01-10")
        self.assertTrue(prescription.is_active(date(2030, 1, 9)))
        self.assertFalse(prescription.is_active(date(2030, 1, 10)))
        self.issue("Amoxicillin", start="2030-01-10")

    def test_status_through_a_course(self):
        prescription = self.issue()
        self.assertEqual(prescription.status(date(2030, 1, 6)), "upcoming")
        self.assertEqual(prescription.status(date(2030, 1, 7)), "active")
        self.assertEqual(prescription.status(date(2030, 1, 13)), "active")
        self.assertEqual(prescription.status(date(2030, 1, 14)), "ended")
        self.tracker.stop_prescription(prescription.id, "2030-01-10")
        self.assertEqual(prescription.status(date(2030, 1, 9)), "active")
        self.assertEqual(prescription.status(date(2030, 1, 10)), "stopped 2030-01-10")

    def test_course_stopped_before_starting_blocks_nothing(self):
        prescription = self.issue("Amoxicillin", start="2030-01-10", days=7)
        self.tracker.stop_prescription(prescription.id, "2030-01-08")
        self.assertFalse(prescription.is_active(date(2030, 1, 10)))
        self.issue("Amoxicillin", start="2030-01-07", days=30)

    def test_stop_rules(self):
        prescription = self.issue()
        with self.assertRaises(ConflictError):
            self.tracker.stop_prescription(prescription.id, "2030-01-14")
        self.tracker.stop_prescription(prescription.id, "2030-01-13")
        with self.assertRaises(ConflictError):
            self.tracker.stop_prescription(prescription.id, "2030-01-13")

    def test_ending_soon_boundaries_and_order(self):
        later = self.issue("A", days=7)
        sooner = self.issue("B", days=3)
        future = self.issue("C", start="2030-02-01", days=3)
        stopped = self.issue("D", days=2)
        self.tracker.stop_prescription(stopped.id, "2030-01-07")
        result = self.tracker.prescriptions_ending_soon(6, today=TODAY)
        self.assertEqual(result, [sooner, later])
        self.assertEqual(self.tracker.prescriptions_ending_soon(5, today=TODAY), [sooner])
        self.assertNotIn(future, result)
        with self.assertRaises(ValidationError):
            self.tracker.prescriptions_ending_soon(-1, today=TODAY)

    def test_list_filters(self):
        first = self.issue("A")
        second = self.issue("B", start="2030-03-01")
        self.assertEqual(self.tracker.list_prescriptions(), [second, first])
        self.assertEqual(self.tracker.list_prescriptions(active_on="2030-01-08"), [first])
        self.assertEqual(self.tracker.list_prescriptions(client_id=self.client2), [])


class StorageTests(TrackerTestCase):
    def setUp(self):
        super().setUp()
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        self.path = os.path.join(directory.name, "data.json")

    def test_round_trip_keeps_records_and_rules(self):
        kept = self.book("2030-01-08 09:00")
        cancelled = self.book("2030-01-08 10:00")
        self.tracker.cancel_appointment(cancelled.id)
        prescription = self.tracker.issue_prescription(
            self.client, self.pro, "Ibuprofen", "200 mg", 2, "2030-01-07", 5
        )
        self.tracker.stop_prescription(prescription.id, "2030-01-09")
        self.tracker.save(self.path)

        loaded = MediTrack.load(self.path)
        self.assertEqual(loaded.appointments, self.tracker.appointments)
        self.assertEqual(loaded.prescriptions, self.tracker.prescriptions)
        self.assertEqual(loaded.clients, self.tracker.clients)
        self.assertEqual(loaded.professionals, self.tracker.professionals)
        with self.assertRaises(ConflictError):
            loaded.book_appointment(self.pro, self.client, kept.start, 30, "Clash", now=NOW)
        loaded.book_appointment(self.pro, self.client, cancelled.start, 30, "Free", now=NOW)
        self.assertEqual(loaded.add_client("New", "2000-01-01", "01782 733000").id, "CLI-0003")

    def test_missing_file_gives_empty_tracker(self):
        self.assertEqual(MediTrack.load(self.path).clients, {})

    def test_corrupt_files_rejected_and_left_alone(self):
        bad_contents = [
            "{not json",
            "[]",
            json.dumps({"version": 99}),
            json.dumps({"version": 1, "professionals": []}),
        ]
        for content in bad_contents:
            with self.subTest(content=content):
                with open(self.path, "w", encoding="utf-8") as file:
                    file.write(content)
                with self.assertRaises(DataFileError):
                    MediTrack.load(self.path)
                with open(self.path, encoding="utf-8") as file:
                    self.assertEqual(file.read(), content)

    def _load_edited(self, edit):
        self.book("2030-01-08 09:00")
        self.book("2030-01-08 10:00")
        self.tracker.save(self.path)
        with open(self.path, encoding="utf-8") as file:
            data = json.load(file)
        edit(data)
        with open(self.path, "w", encoding="utf-8") as file:
            json.dump(data, file)
        return MediTrack.load(self.path)

    def test_overlapping_scheduled_data_rejected(self):
        def edit(data):
            data["appointments"][1]["start"] = "2030-01-08 09:00"

        with self.assertRaises(DataFileError):
            self._load_edited(edit)

    def test_dangling_reference_rejected(self):
        def edit(data):
            data["appointments"][0]["client_id"] = "CLI-9999"

        with self.assertRaises(DataFileError):
            self._load_edited(edit)

    def test_save_failure_reported_and_leaves_no_temp_file(self):
        self.tracker.save(self.path)
        with mock.patch("os.replace", side_effect=OSError("disk full")):
            with self.assertRaises(DataFileError):
                self.tracker.save(self.path)
        self.assertEqual(os.listdir(os.path.dirname(self.path)), ["data.json"])

    @unittest.skipIf(os.name != "posix", "POSIX permissions only")
    def test_data_file_is_private_to_owner(self):
        self.tracker.save(self.path)
        self.assertEqual(os.stat(self.path).st_mode & 0o777, 0o600)


class TextAppTests(unittest.TestCase):
    def setUp(self):
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        self.path = os.path.join(directory.name, "data.json")

    def run_app(self, *answers):
        tracker = MediTrack.load(self.path)
        output = io.StringIO()
        with mock.patch("builtins.input", side_effect=list(answers)):
            with contextlib.redirect_stdout(output):
                text_app.TextApp(tracker, self.path).run()
        return output.getvalue()

    def test_full_journey_persists(self):
        output = self.run_app(
            "1", "Dr Ada Obi", "Cardiology",
            "3", "Ann Lee", "1990-05-01", "01782 733000",
            "5", "PRO-0001", "CLI-0001", "2099-01-05 09:00", "30", "Check-up",
            "11", "CLI-0001", "PRO-0001", "Ibuprofen", "200 mg", "2", "2099-01-05", "5",
            "0",
        )
        self.assertIn("Booked APT-0001.", output)
        self.assertIn("Issued RX-0001: 10 doses, ending 2099-01-09.", output)

        output = self.run_app("7", "", "", "", "", "12", "", "n", "0")
        self.assertIn("Check-up", output)
        self.assertIn("Ibuprofen", output)

    def test_invalid_input_reprompts(self):
        output = self.run_app("3", "", "Ann Lee", "not-a-date", "2999-01-01", "1990-05-01", "x", "01782 733000", "0")
        self.assertIn("Name is required.", output)
        self.assertIn("YYYY-MM-DD", output)
        self.assertIn("cannot be in the future", output)
        self.assertIn("Phone must be", output)
        self.assertIn("Added CLI-0001.", output)

    def test_cancel_and_bad_menu_choice(self):
        output = self.run_app("99", "abc", "1", "cancel", "0")
        self.assertIn("Please enter a number", output)
        self.assertIn("Cancelled.", output)
        self.assertFalse(os.path.exists(self.path))

    def test_clash_is_reported_not_raised(self):
        self.run_app(
            "1", "Dr Ada Obi", "Cardiology",
            "3", "Ann Lee", "1990-05-01", "01782 733000",
            "5", "PRO-0001", "CLI-0001", "2099-01-05 09:00", "30", "First",
            "0",
        )
        output = self.run_app(
            "5", "PRO-0001", "CLI-0001", "2099-01-05 09:15", "30", "Second", "0"
        )
        self.assertIn("Could not do that: The professional already has APT-0001", output)


class GuiTests(unittest.TestCase):
    """Drive the same features through the window, hidden from view."""

    def setUp(self):
        try:
            import tkinter

            self.root = tkinter.Tk()
        except Exception as error:  # No Tk or no display on this machine.
            self.skipTest(f"Tk is unavailable: {error}")
        self.root.withdraw()
        self.addCleanup(self.root.destroy)
        import gui

        self.gui = gui
        directory = tempfile.TemporaryDirectory()
        self.addCleanup(directory.cleanup)
        self.path = os.path.join(directory.name, "data.json")
        self.app = gui.MediTrackApp(self.root, MediTrack(), self.path)
        patcher = mock.patch.object(gui.messagebox, "showerror")
        self.showerror = patcher.start()
        self.addCleanup(patcher.stop)

    def set_fields(self, **values):
        for key, value in values.items():
            self.app.fields[key].set(value)

    def add_people(self):
        self.set_fields(pro_name="Dr Ada Obi", pro_specialty="Cardiology")
        self.app.add_professional()
        self.set_fields(cli_name="Ann Lee", cli_dob="1990-05-01", cli_phone="01782 733000")
        self.app.add_client()
        return {
            "apt_pro_choice": "PRO-0001  Dr Ada Obi",
            "apt_cli_choice": "CLI-0001  Ann Lee",
        }

    def book(self, start="2099-01-05 09:00"):
        self.set_fields(
            **self.add_choice, apt_start=start, apt_duration="30", apt_reason="Check-up"
        )
        self.app.book_appointment()

    def test_add_people_updates_tables_and_saves(self):
        self.add_people()
        self.assertEqual(self.app.professional_table.get_children(), ("PRO-0001",))
        self.assertEqual(self.app.client_table.get_children(), ("CLI-0001",))
        self.assertEqual(self.app.fields["cli_name"].get(), "")
        self.assertIn("CLI-0001", MediTrack.load(self.path).clients)

    def test_invalid_input_shows_error_and_keeps_typed_values(self):
        self.set_fields(cli_name="Ann Lee", cli_dob="bad", cli_phone="01782 733000")
        self.app.add_client()
        self.showerror.assert_called_once()
        self.assertEqual(self.app.fields["cli_name"].get(), "Ann Lee")
        self.assertEqual(self.app.client_table.get_children(), ())

    def test_search_filters_clients_as_you_type(self):
        self.add_people()
        self.set_fields(cli_search="nobody")
        self.assertEqual(self.app.client_table.get_children(), ())
        self.set_fields(cli_search="ann")
        self.assertEqual(self.app.client_table.get_children(), ("CLI-0001",))

    def test_appointment_lifecycle(self):
        self.add_choice = self.add_people()
        self.book()
        table = self.app.appointment_table
        self.assertEqual(table.get_children(), ("APT-0001",))

        self.book()  # Same time again: clash.
        self.showerror.assert_called_once()
        self.assertEqual(table.get_children(), ("APT-0001",))

        self.app.cancel_appointment()  # Nothing selected.
        self.assertEqual(self.showerror.call_count, 2)

        table.selection_set("APT-0001")
        self.root.update()
        self.assertEqual(self.app.fields["apt_start"].get(), "2099-01-05 09:00")
        self.set_fields(apt_start="2099-01-05 10:00")
        self.app.reschedule_appointment()
        self.assertEqual(
            self.app.tracker.get_appointment("APT-0001").start, datetime(2099, 1, 5, 10, 0)
        )

        table.selection_set("APT-0001")
        self.app.cancel_appointment()
        self.assertEqual(MediTrack.load(self.path).get_appointment("APT-0001").status, CANCELLED)

    def test_free_slot_fills_start_field(self):
        self.add_choice = self.add_people()
        self.book("2099-01-05 09:00")  # A Monday.
        self.set_fields(
            **self.add_choice, apt_start="2099-01-05 09:00", apt_duration="30"
        )
        self.app.find_free_slot()
        self.assertEqual(self.app.fields["apt_start"].get(), "2099-01-05 09:30")

    def test_filters(self):
        self.add_choice = self.add_people()
        self.book()
        self.set_fields(flt_status_choice="cancelled")
        self.app.apply_appointment_filters()
        self.assertEqual(self.app.appointment_table.get_children(), ())
        self.app.clear_appointment_filters()
        self.assertEqual(self.app.appointment_table.get_children(), ("APT-0001",))

    def test_bad_filter_shows_an_error(self):
        self.set_fields(flt_date="not-a-date")
        self.app.apply_appointment_filters()
        self.showerror.assert_called_once()

    def test_unapplied_bad_filter_does_not_affect_other_actions(self):
        self.set_fields(flt_date="not-a-date", rxf_within="nope")
        self.set_fields(pro_name="Dr Ada Obi", pro_specialty="Cardiology")
        self.app.add_professional()
        self.showerror.assert_not_called()
        self.assertEqual(self.app.status.get(), "Added PRO-0001.")

    def test_typed_filter_waits_for_apply(self):
        self.add_choice = self.add_people()
        self.book()
        self.set_fields(flt_status_choice="cancelled")
        self.set_fields(pro_name="Dr Sam Roy", pro_specialty="Dermatology")
        self.app.add_professional()
        self.assertEqual(self.app.appointment_table.get_children(), ("APT-0001",))

    def test_prescription_lifecycle(self):
        self.add_people()
        self.set_fields(
            rx_cli_choice="CLI-0001  Ann Lee",
            rx_pro_choice="PRO-0001  Dr Ada Obi",
            rx_medication="Ibuprofen",
            rx_dose="200 mg",
            rx_times="2",
            rx_start=date.today().isoformat(),
            rx_days="5",
        )
        self.app.issue_prescription()
        table = self.app.prescription_table
        self.assertEqual(table.get_children(), ("RX-0001",))

        self.set_fields(rxf_within="10")
        self.app.apply_prescription_filters()
        self.assertEqual(table.get_children(), ("RX-0001",))
        self.app.clear_prescription_filters()

        table.selection_set("RX-0001")
        self.app.stop_prescription()
        self.assertIsNotNone(MediTrack.load(self.path).get_prescription("RX-0001").stopped_on)


if __name__ == "__main__":
    unittest.main()
